import java.io.BufferedInputStream
import java.io.FileInputStream
import java.io.File
import java.io.PrintWriter
import java.util.*

const val MAX = 511
const val MOD = 998244353
const val INV = 499122177

fun mult(a: Int, b: Int): Int {
    var aa = a.toLong()
    var bb = b.toLong()
    if (aa >= MOD) aa -= MOD
    if (bb >= MOD) bb -= MOD
    aa = (aa * bb) % MOD
    return aa.toInt()
}

fun add(a: Int, b: Int): Int {
    var aa = a
    var bb = b
    if (aa >= MOD) aa -= MOD
    if (bb >= MOD) bb -= MOD
    aa += bb
    if (aa >= MOD) aa -= MOD
    return aa
}

class FastScanner {
    private val BS = 1 shl 16
    private val NC = 0.toChar()
    private val buf = ByteArray(BS)
    private var bId = 0
    private var size = 0
    private var c = NC
    private var num = 1.0
    private val `in`: BufferedInputStream

    constructor() {
        `in` = BufferedInputStream(System.`in`, BS)
    }

    constructor(s: String) {
        `in` = BufferedInputStream(FileInputStream(File(s)), BS)
    }

    private fun nextChar(): Char {
        while (bId == size) {
            try {
                size = `in`.read(buf)
            } catch (e: Exception) {
                return NC
            }
            if (size == -1) return NC
            bId = 0
        }
        return buf[bId++].toChar()
    }

    fun nextInt(): Int = nextLong().toInt()

    fun nextLong(): Long {
        num = 1.0
        var neg = false
        if (c == NC) c = nextChar()
        while (c < '0' || c > '9') {
            if (c == '-') neg = true
            c = nextChar()
        }
        var res = 0L
        while (c >= '0' && c <= '9') {
            res = (res shl 3) + (res shl 1) + (c - '0')
            num *= 10
            c = nextChar()
        }
        return if (neg) -res else res
    }

    fun nextDouble(): Double {
        val cur = nextLong()
        return if (c != '.') cur.toDouble() else cur + nextLong() / num
    }

    fun next(): String {
        val res = StringBuilder()
        while (c <= ' ') c = nextChar()
        while (c > ' ') {
            res.append(c)
            c = nextChar()
        }
        return res.toString()
    }

    fun nextLine(): String {
        val res = StringBuilder()
        while (c <= ' ') c = nextChar()
        while (c != '\n') {
            res.append(c)
            c = nextChar()
        }
        return res.toString()
    }

    fun hasNext(): Boolean {
        if (c > ' ') return true
        while (true) {
            c = nextChar()
            if (c == NC) return false
            else if (c > ' ') return true
        }
    }

    fun nextIntArray(n: Int): IntArray {
        val res = IntArray(n)
        for (i in 0 until n) res[i] = nextInt()
        return res
    }
}

fun main() {
    val fs = FastScanner()
    val out = PrintWriter(System.out)
    System.err.println("Go!")

    val n = fs.nextInt()
    val k = fs.nextInt()
    if (n == 1) {
        println(0)
        return
    }

    var dp = Array(MAX) { IntArray(MAX) }
    dp[1][1] = 2
    for (pos in 0 until n) {
        val ndp = Array(MAX) { IntArray(MAX) }
        val lim = minOf(k, n)
        for (i in 1..lim) {
            for (j in 1..lim) {
                val nm = maxOf(i, j + 1)
                ndp[nm][j + 1] = add(ndp[nm][j + 1], dp[i][j])
                ndp[i][1] = add(ndp[i][1], dp[i][j])
            }
        }
        if (pos != n - 1) dp = ndp
    }

    val nums = IntArray(MAX)
    val div2 = IntArray(MAX)
    val lim = minOf(n, k)
    for (i in 1..lim) {
        for (j in 1..lim) {
            nums[i] = add(nums[i], dp[i][j])
        }
    }
    for (i in 1..n) {
        div2[i] = mult(nums[i], INV)
    }

    var res = 0
    for (i in 1..lim) {
        for (j in 1..lim) {
            if (i * j < k) {
                res = add(res, mult(2, mult(div2[i], div2[j])))
            }
        }
    }

    out.println(res)
    out.close()
}

